"""OBSOLETE (7 Oct 2026): Experiment 3 (text generated by Claude Haiku 4.5) was removed from the paper; kept for the record, not run by run_all.sh.
Experiment 3 diagnostics (run after exp3_llm.py):
  (0) regenerate exp2_text_power.pdf with the gamma label from exp2_text_power.csv;
  (1) learning curve of rho_hat in n from exp3_llm_subsample_raw.csv  -> exp3_llm_learning_curve.pdf;
  (2) exact model-X (CRT) reference on the 500-row subsample with M = 19 regenerated comments (B_draws in the code) -> exp3_llm_crt.pdf;
  (3) truncation statistics and short/long-post subsets;
  (4) alternative views of Z (full-window mpnet, chunked encoders, surface features, TF-IDF SVD)
      as psi and as benchmark psi'                                          -> exp3_llm_benchmarks.pdf.
All numbers go to results/exp3_diagnostics.json (written after every block)."""
from __future__ import annotations
import json, re, sys, time
from pathlib import Path
import numpy as np, pandas as pd
import matplotlib; matplotlib.use("Agg")
import matplotlib.pyplot as plt
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from citext import plotting as P
from citext.estimators import (gcm_test, gcm_from_residuals, fit_predict_crossfit, crossfit_folds,
                               benchmark_pair, rv_alpha)
from citext.paths import RESULTS_DIR, CACHE_DIR
from citext.text_semi import E1_NAME, E2_NAME, embed_texts, _device, _safe
from sklearn.linear_model import RidgeCV

LLM = Path.home() / ".cache/ci_text/llm"
GEN = LLM / "gen_claude-haiku-4-5_n3000.jsonl"
CRT = LLM / "crt_claude-haiku-4-5_n500_B19.jsonl"
OUT = RESULTS_DIR / "exp3_diagnostics.json"
REG, K, SEED, ALPHA = "ridge", 5, 0, 0.05   # ridge throughout in Experiment 3 (30 Sept 2026), as in exp3_llm.py
LABEL_SCORE = {"POSITIVE": 1.0, "NEUTRAL": 0.0, "NEGATIVE": -1.0}
res: dict = {}
t0 = time.time()
def log(*a): print(f"[{time.time()-t0:6.0f}s]", *a, flush=True)
def save(): OUT.write_text(json.dumps(res, indent=1, default=float))

# (0) removed on 29 Sept 2026: exp2_text.py --only plots owns exp2_text_power.pdf

# ---------------------------------------------------------------- (1) learning curve
try:
    raw = pd.read_csv(RESULTS_DIR / "exp3_llm_subsample_raw.csv")
    full = pd.read_csv(RESULTS_DIR / "exp3_llm_full_sample.csv")
    meta = json.loads((RESULTS_DIR / "summary_exp3.json").read_text())
    marg = meta["sentiment_following"]
    raw = raw[(raw.axis == "sentiment") & (raw.reg == REG)]
    agg = raw.groupby(["hyp", "psi", "n"]).rho.agg(med="median", lo=lambda s: s.quantile(.25), hi=lambda s: s.quantile(.75)).reset_index()
    res["learning_curve"] = agg.to_dict("records")
    P.setup(); fig, axs = plt.subplots(1, 2, figsize=P.DOUBLE, sharey=True)
    cols = {"E1": P.CAT[0], "E2": P.CAT[1], "E1+E2": P.CAT[2]}
    labs = {"E1": r"$\psi=E_1(Z)$", "E2": r"$\psi=E_2(Z)$", "E1+E2": r"$\psi=[E_1,E_2](Z)$"}
    for ax, hyp, title, m in zip(axs, ("H0", "H1"), (r"$H_0$: $Y$ generated from $Z$ alone", r"$H_1$: $Y$ matches the sentiment of $X$"),
                                 (marg["corr_A_B0"], marg["corr_A_B1"])):
        for psi in ("E1", "E2", "E1+E2"):
            a = agg[(agg.hyp == hyp) & (agg.psi == psi)].sort_values("n")
            f = full[(full.axis == "sentiment") & (full.hyp == hyp) & (full.psi == psi) & (full.reg == REG)]
            ns = list(a.n) + [3000]; med = list(a.med) + [float(f.rho_hat.iloc[0])]
            lo = list(a.lo) + [float(f.rho_hat.iloc[0] - 1.96 * f.se.iloc[0])]; hi = list(a.hi) + [float(f.rho_hat.iloc[0] + 1.96 * f.se.iloc[0])]
            ax.fill_between(ns, lo, hi, color=cols[psi], alpha=0.15, linewidth=0)
            ax.plot(ns, med, marker="o", color=cols[psi], label=labs[psi])
        ax.axhline(m, color=P.MUTED, ls=":", lw=0.9); ax.annotate("unadjusted correlation of $X$ and $Y$", (500, m), xytext=(2, 3), textcoords="offset points", fontsize=6.5, color=P.INK2)
        ax.axhline(0, color=P.AXIS, lw=0.6); ax.set_xscale("log"); ax.set_xticks([500, 1000, 2000, 3000]); ax.set_xticklabels(["500", "1000", "2000", "3000"])
        ax.set_xlabel("sample size $n$"); ax.set_title(title)
    axs[0].set_ylabel(r"residual correlation $\hat\rho$"); axs[0].legend(loc="lower left")
    P.savefig(fig, "exp3_llm_learning_curve.pdf"); save(); log("learning curve figure done")
except Exception as e:
    log("learning curve FAILED:", repr(e))

# ---------------------------------------------------------------- data + embeddings
rows = [json.loads(l) for l in GEN.read_text().splitlines() if l.strip()]
rows = [r for r in rows if r["X"] and r["Y0"] and r["Y1"]]; rows.sort(key=lambda r: r["idx"])
n = len(rows); idx_all = np.array([r["idx"] for r in rows])
Z = [r["Z"] for r in rows]; X = [r["X"] for r in rows]; Y0 = [r["Y0"] for r in rows]
s = np.array([LABEL_SCORE.get(r["X_label"], 0.0) for r in rows])
log(f"{n} rows loaded")

def embed_len(texts, model_name, max_len, key, chunk_words=None):
    """Embeddings with a chosen window; if chunk_words is set, average chunk embeddings (length-weighted)."""
    f = CACHE_DIR / f"emb_diag_{key}_{_safe(model_name)}_{max_len}_{chunk_words or 0}.npy"
    if f.exists():
        return np.load(f)
    from sentence_transformers import SentenceTransformer
    model = SentenceTransformer(model_name, cache_folder=str(CACHE_DIR / "st_models"), device=_device())
    model.max_seq_length = max_len
    if chunk_words is None:
        E = model.encode(list(texts), batch_size=64, show_progress_bar=False, convert_to_numpy=True)
    else:
        chunks, owner, weight = [], [], []
        for i, t in enumerate(texts):
            w = t.split(" ")
            for j in range(0, len(w), chunk_words):
                c = w[j:j + chunk_words]; chunks.append(" ".join(c)); owner.append(i); weight.append(len(c))
        Ec = model.encode(chunks, batch_size=64, show_progress_bar=False, convert_to_numpy=True)
        owner = np.array(owner); weight = np.array(weight, dtype=float)
        E = np.zeros((len(texts), Ec.shape[1]))
        np.add.at(E, owner, Ec * weight[:, None]); E /= np.bincount(owner, weights=weight, minlength=len(texts))[:, None]
    E = np.asarray(E, dtype=np.float64); np.save(f, E); return E

E1Z = embed_texts(Z, E1_NAME, "diagZ"); E1X = embed_texts(X, E1_NAME, "diagX"); E1Y0 = embed_texts(Y0, E1_NAME, "diagY0")
E2Z = embed_texts(Z, E2_NAME, "diagZ")            # 256-token window, as in the main experiment
log("base embeddings done")

def sentiment_axis(EX, s, EY0, K=5, seed=0):
    A, B0 = np.empty(len(s)), np.empty(len(s))
    for tr, te in crossfit_folds(len(s), K, seed):
        m = RidgeCV(alphas=np.logspace(-2, 4, 13)).fit(EX[tr], s[tr]); A[te], B0[te] = m.predict(EX[te]), m.predict(EY0[te])
    return A, B0
A, B0 = sentiment_axis(E1X, s, E1Y0)
folds = crossfit_folds(n, K, SEED)

# ---------------------------------------------------------------- (2) CRT reference
try:
    crt = [json.loads(l) for l in CRT.read_text().splitlines() if l.strip()]
    draws: dict = {}
    for r in crt:
        draws.setdefault(r["idx"], {})[r["b"]] = r["X_prime"]
    B_draws = 19
    sub_idx = sorted(i for i, d in draws.items() if len(d) >= B_draws)
    pos = {ix: k for k, ix in enumerate(idx_all)}
    sub = np.array([pos[i] for i in sub_idx]); rest = np.setdiff1d(np.arange(n), sub)
    w = RidgeCV(alphas=np.logspace(-2, 4, 13)).fit(E1X[rest], s[rest])       # fixed direction, fitted outside the subsample
    A_sub = w.predict(E1X[sub]); B_sub = w.predict(E1Y0[sub]); Psi_sub = E1Z[sub]
    f_sub = crossfit_folds(len(sub), K, SEED)
    rB = B_sub - fit_predict_crossfit(Psi_sub, B_sub, K, SEED, REG, f_sub)
    rA = A_sub - fit_predict_crossfit(Psi_sub, A_sub, K, SEED, REG, f_sub)
    obs = gcm_from_residuals(rA, rB, ALPHA)
    texts_b = [draws[i][b] for b in range(B_draws) for i in sub_idx]
    Eb = embed_texts(texts_b, E1_NAME, f"diagXprime_{len(sub)}x{B_draws}").reshape(B_draws, len(sub), -1)
    rho_b = []
    for b in range(B_draws):
        Ab = w.predict(Eb[b]); rAb = Ab - fit_predict_crossfit(Psi_sub, Ab, K, SEED, REG, f_sub)
        rho_b.append(gcm_from_residuals(rAb, rB, ALPHA).rho_hat)
    rho_b = np.array(rho_b)
    p_crt = (1 + np.sum(np.abs(rho_b) >= abs(obs.rho_hat))) / (B_draws + 1)
    res["crt"] = {"n_sub": int(len(sub)), "B": B_draws, "rho_obs": obs.rho_hat, "se_obs": obs.se, "z_obs": obs.rho_hat / obs.se,
                  "p_embedded": obs.pvalue, "rho_draws": rho_b.tolist(), "p_crt": float(p_crt),
                  "rho_draws_mean": float(rho_b.mean()), "rho_draws_sd": float(rho_b.std(ddof=1))}
    save(); log(f"CRT: rho_obs={obs.rho_hat:.3f} (se {obs.se:.3f}), draws mean {rho_b.mean():.3f} sd {rho_b.std(ddof=1):.3f}, p_crt={p_crt:.3f}")
    P.setup(); fig, ax = plt.subplots(figsize=P.SINGLE)
    ax.axvspan(-1.96 * obs.se, 1.96 * obs.se, color=P.CAT[1], alpha=0.15, lw=0)
    ax.annotate("acceptance region of the\nembedded test", (0, 0.04), xytext=(0, 0), textcoords="offset points", ha="center", va="bottom", fontsize=6.5, color=P.INK2)
    rng = np.random.default_rng(0); yj = rng.uniform(0.15, 0.35, size=B_draws)
    ax.scatter(rho_b, yj, s=18, color=P.CAT[0], label=rf"$\hat\rho$ for regenerated comments ($M={B_draws}$)", zorder=3)
    ax.scatter([obs.rho_hat], [0.25], s=40, marker="D", color=P.CAT[7], label=r"observed $\hat\rho$", zorder=4)
    ax.set_yticks([]); ax.set_ylim(0, 0.6); ax.set_xlabel(r"residual correlation $\hat\rho$ ($\psi=E_1$, $n'=%d$)" % len(sub))
    ax.legend(loc="upper right"); ax.set_xlim(min(-0.1, rho_b.min() - 0.03), max(rho_b.max(), obs.rho_hat) + 0.05)
    P.savefig(fig, "exp3_llm_crt.pdf"); log("CRT figure done")
except Exception as e:
    log("CRT FAILED:", repr(e))

# ---------------------------------------------------------------- (3) truncation + subsets
try:
    from sentence_transformers import SentenceTransformer
    lens = {}
    for name in (E1_NAME, E2_NAME):
        m = SentenceTransformer(name, cache_folder=str(CACHE_DIR / "st_models"), device="cpu")
        ids = m.tokenizer(Z, add_special_tokens=True, truncation=False)["input_ids"]
        lens[name] = np.array([len(x) for x in ids])
    L1 = lens[E1_NAME]
    res["truncation"] = {name: {"median_tokens": float(np.median(l)), "mean_tokens": float(l.mean()),
                                "frac_over_256": float((l > 256).mean()), "frac_over_384": float((l > 384).mean()),
                                "note": "posts were cut to 300 words before generation; both encoders used a 256-token window in the main experiment"}
                         for name, l in lens.items()}
    wcZ = np.array([len(z.split()) for z in Z]); wcX = np.array([len(x.split()) for x in X]); wcY = np.array([len(y.split()) for y in Y0])
    res["word_counts"] = {"corr_A_wcX": float(np.corrcoef(A, wcX)[0, 1]), "corr_B_wcY": float(np.corrcoef(B0, wcY)[0, 1]),
                          "corr_A_wcZ": float(np.corrcoef(A, wcZ)[0, 1]), "corr_B_wcZ": float(np.corrcoef(B0, wcZ)[0, 1]),
                          "corr_wcX_wcY": float(np.corrcoef(wcX, wcY)[0, 1]), "median_wcZ": float(np.median(wcZ))}
    short = np.where(L1 <= 256)[0]; longp = np.where(L1 > 256)[0]
    res["subsets"] = {}
    for label, ix in (("short_posts_fit_in_window", short), ("long_posts_truncated", longp)):
        r = gcm_test(A[ix], B0[ix], E1Z[ix], regressor=REG, seed=SEED, alpha=ALPHA)
        res["subsets"][label] = {"n": int(len(ix)), "rho_hat": r.rho_hat, "se": r.se}
        log(f"subset {label}: n={len(ix)} rho={r.rho_hat:.3f} se={r.se:.3f}")
    save()
except Exception as e:
    log("truncation/subsets FAILED:", repr(e))

# ---------------------------------------------------------------- (4) alternative views of Z
try:
    def surface(texts):
        F = []
        for t in texts:
            w = t.split(); nc = max(len(t), 1)
            F.append([np.log1p(len(w)), np.log1p(len(t)), len(re.findall(r"[.!?]+", t)), sum(c.isupper() for c in t) / nc,
                      sum(c.isdigit() for c in t) / nc, float(bool(re.search(r"https?://|www\.|@\w+\.\w+", t))),
                      np.mean([len(x) for x in w]) if w else 0.0, sum(c in ",;:()\"'-" for c in t) / nc])
        return np.array(F)
    S = surface(Z)
    from sklearn.feature_extraction.text import TfidfVectorizer
    from sklearn.decomposition import TruncatedSVD
    Tf = TfidfVectorizer(min_df=3, max_df=0.9, sublinear_tf=True, max_features=30000).fit_transform(Z)
    L300 = TruncatedSVD(300, random_state=0).fit_transform(Tf)
    E2full = embed_len(Z, E2_NAME, 384, "Z")               # mpnet with its native window
    E1c = embed_len(Z, E1_NAME, 256, "Z", chunk_words=150) # full-coverage chunked encoders
    E2c = embed_len(Z, E2_NAME, 384, "Z", chunk_words=200)
    views = {"E1": E1Z, "E2": E2Z, "E1+E2": np.hstack([E1Z, E2Z]), "E2full": E2full, "E1c": E1c, "E2c": E2c,
             "E1+S": np.hstack([E1Z, S]), "E1+L300": np.hstack([E1Z, L300]), "E1+S+L300": np.hstack([E1Z, S, L300]),
             "E1c+S+L300": np.hstack([E1c, S, L300])}
    res["views"] = {}
    for name, Psi in views.items():
        pA = fit_predict_crossfit(Psi, A, K, SEED, REG, folds); pB = fit_predict_crossfit(Psi, B0, K, SEED, REG, folds)
        rA, rB = A - pA, B0 - pB; r = gcm_from_residuals(rA, rB, ALPHA)
        res["views"][name] = {"dim": int(Psi.shape[1]), "rho_hat": r.rho_hat, "se": r.se, "RV_alpha": r.RV_alpha,
                              "R2_A": float(1 - np.mean(rA**2) / np.var(A)), "R2_B": float(1 - np.mean(rB**2) / np.var(B0))}
        save(); log(f"view {name}: rho={r.rho_hat:.3f} se={r.se:.3f} R2A={res['views'][name]['R2_A']:.3f} R2B={res['views'][name]['R2_B']:.3f}")
    res["benchmarks_from_E1"] = {}
    for name, Pp in (("E2", E2Z), ("E2full", E2full), ("E1c", E1c), ("E2c", E2c), ("S", S), ("L300", L300), ("S+L300", np.hstack([S, L300])), ("E1c+S+L300", np.hstack([E1c, S, L300]))):
        b = benchmark_pair(A, B0, E1Z, Pp, regressor=REG, K=K, seed=SEED)
        res["benchmarks_from_E1"][name] = {"r2_A": b["r2_A"], "r2_B": b["r2_B"], "rho_bench": b["bench"]}
        save(); log(f"bench E1->{name}: r2A={b['r2_A']:.3f} r2B={b['r2_B']:.3f} rho_bench={b['bench']:.3f}")
    # figure
    order = ["E1", "E2", "E1+E2", "E2full", "E1c", "E2c", "E1+S", "E1+L300", "E1+S+L300", "E1c+S+L300"]
    labels = {"E1": "$E_1$", "E2": "$E_2$", "E1+E2": "$[E_1,E_2]$", "E2full": "$E_2$ (384)", "E1c": "$E_1^{c}$", "E2c": "$E_2^{c}$",
              "E1+S": "$[E_1,S]$", "E1+L300": "$[E_1,L]$", "E1+S+L300": "$[E_1,S,L]$", "E1c+S+L300": "$[E_1^{c},S,L]$"}
    bench_of = {"E2": "E2", "E1+E2": "E2", "E2full": "E2full", "E1c": "E1c", "E2c": "E2c", "E1+S": "S", "E1+L300": "L300", "E1+S+L300": "S+L300", "E1c+S+L300": "E1c+S+L300"}
    P.setup(); fig, ax = plt.subplots(figsize=(6.6, 2.5)); xs = np.arange(len(order))
    rh = [res["views"][k]["rho_hat"] for k in order]; se = [res["views"][k]["se"] for k in order]
    ax.errorbar(xs, rh, yerr=1.96 * np.array(se), fmt="o", color=P.CAT[0], capsize=2, label=r"$\hat\rho$ under $H_0$ with $\psi$ ($\pm 1.96$ se)")
    bx = [i for i, k in enumerate(order) if k in bench_of]; bv = [res["benchmarks_from_E1"][bench_of[order[i]]]["rho_bench"] for i in bx]
    ax.scatter(bx, bv, marker="s", color=P.CAT[1], s=28, zorder=3, label=r"insufficiency of $E_1$ demonstrated by the added view, $\hat\rho_{\mathrm{bench}}$")
    ax.axhline(0, color=P.AXIS, lw=0.6); ax.set_xticks(xs); ax.set_xticklabels([labels[k] for k in order], fontsize=7)
    ax.set_ylabel("value"); ax.legend(loc="upper right", fontsize=6.5); P.savefig(fig, "exp3_llm_benchmarks.pdf"); log("benchmarks figure done")
except Exception as e:
    log("views FAILED:", repr(e))
res["wall_time_s"] = time.time() - t0; save(); log("ALL DONE")
